        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amt);
        vm.assume(c.Owner() == address(this));
        bool ok = true;
        try c.withdraw{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }

    function testFuzz_test(uint256 amt) public {
        _test(amt);
    }

